"""Checkout orchestration."""

from .pricing import calculate_[total]


def checkout(prices: list[int], [discount]: int = 0) -> dict:
    """Create a checkout summary in cents."""
    return {"[total]": calculate_[total](prices, [discount]), "currency": "BRL"}

